Ниже представлен готовый JavaScript-код, составленный **строго по алгоритмам и принципам** из документов `connecting_a_new_portalinstruction.md` и `INSTRUCTION_OK_ATOMS_A1_A6.md`. 

Этот код предназначен для вставки в **Console** DevTools (F12) браузера Edge на странице ОК. Он находит контейнер события для выбранного элемента и **фиксирует собранный фрагмент** в точном формате 15-секционного отчёта (секция `[04]`), а также копирует его в буфер обмена.

### 🛠️ Код для вставки в Console (F12)

```javascript
(function() {
    // 1. Проверяем, что элемент выбран в панели Elements
    const el = typeof $0 !== 'undefined' ? $0 : null;
    if (!el || el === document.body) {
        console.error('❌ ОШИБКА: Элемент не выбран.\n👉 Пожалуйста, выберите имя автора, текст комментария или поста в панели Elements (F12), затем запустите этот код снова.');
        return;
    }

    console.log(`🔍 Начало анализа выбранного элемента:`, el);

    // 2. Алгоритм поиска EVENT_CONTAINER (строго по принципам connecting_a_new_portalinstruction.md)
    function findEventContainer(element) {
        if (!element) return null;

        // Уровень А: Поиск по явным паттернам классов и ID
        const containers = [
            { test: (e) => e.classList && Array.from(e.classList).some(c => /comment|post|message|entry|item|discuss|thread/i.test(c)), name: 'Matched class pattern (comment/post/message/etc.)' },
            { test: (e) => e.id && /comment|post|message|entry|item/i.test(e.id), name: 'Matched ID pattern' },
            { test: (e) => e.getAttribute('data-test') || e.getAttribute('data-testid'), name: 'Has data-test/data-testid attribute' }
        ];

        let current = element;
        let depth = 0;
        const maxDepth = 10;

        while (current && depth < maxDepth) {
            for (let container of containers) {
                if (container.test(current)) {
                    return {
                        element: current,
                        selector: getCssSelector(current),
                        reason: container.name,
                        depth: depth
                    };
                }
            }
            current = current.parentElement;
            depth++;
        }

        // Уровень Б: Эвристический поиск (контейнер с текстом > 50 символов, содержащий автора)
        current = element.parentElement;
        depth = 0;
        while (current && depth < 7) {
            if (current.children && current.children.length > 1) {
                let hasText = false;
                let hasAuthor = false;

                for (let child of current.children) {
                    const text = (child.textContent || '').trim();
                    if (text.length > 50) hasText = true;
                    if (child === element || child.contains(element)) hasAuthor = true;
                }

                if (hasText && hasAuthor) {
                    return {
                        element: current,
                        selector: getCssSelector(current),
                        reason: 'Probable container with text and author (heuristic)',
                        depth: depth
                    };
                }
            }
            current = current.parentElement;
            depth++;
        }

        // Уровень В: Fallback (крайний случай)
        return {
            element: element.closest('body') || element,
            selector: getCssSelector(element.closest('body') || element),
            reason: 'Fallback to body or nearest parent',
            depth: -1
        };
    }

    // Вспомогательная функция для генерации читаемого CSS-селектора
    function getCssSelector(element) {
        if (element.id) return `#${element.id}`;
        if (element === document.body) return 'body';

        let path = [];
        let curr = element;
        while (curr && curr.nodeType === Node.ELEMENT_NODE) {
            let selector = curr.nodeName.toLowerCase();
            if (curr.className && typeof curr.className === 'string') {
                // Берем только первые 1-2 класса, игнорируя короткие или числовые хэши
                const classes = curr.className.trim().split(/\s+/).filter(c => c.length > 3 && !/^\d+$/.test(c)).slice(0, 2);
                if (classes.length > 0) {
                    selector += '.' + classes.join('.');
                }
            }
            path.unshift(selector);
            curr = curr.parentElement;
            if (path.length > 5) break; // Ограничиваем глубину для читаемости отчёта
        }
        return path.join(' > ');
    }

    // 3. Выполняем поиск
    const result = findEventContainer(el);

    if (!result) {
        console.error('❌ Не удалось определить EVENT_CONTAINER.');
        return;
    }

    // 4. ФИКСАЦИЯ СОБРАННОГО ФРАГМЕНТА (формат отчёта OK_ANALYSIS_GAPS.md)
    const preview = result.element.outerHTML 
        ? result.element.outerHTML.substring(0, 300).replace(/\n/g, ' ').replace(/\s+/g, ' ') + '...' 
        : 'N/A';

    const reportFragment = `[04] EVENT_CONTAINER
Selector: ${result.selector}
Reason: ${result.reason}
Depth: ${result.depth}
Preview: ${preview}`;

    console.log('\n✅ EVENT_CONTAINER НАЙДЕН И ЗАФИКСИРОВАН:');
    console.log('==================================================');
    console.log(reportFragment);
    console.log('==================================================\n');

    // 5. Автоматическое копирование в буфер обмена (нативная функция DevTools)
    try {
        copy(reportFragment);
        console.log('📋 Фрагмент отчёта [04] автоматически скопирован в буфер обмена.');
    } catch (e) {
        console.log('⚠️ Не удалось скопировать автоматически. Пожалуйста, выделите и скопируйте текст выше вручную.');
    }

    // 6. Визуальная проверка: подсветка найденного контейнера на 3 секунды
    if (result.element) {
        const originalOutline = result.element.style.outline;
        result.element.style.outline = '3px solid #ff0000';
        result.element.style.outlineOffset = '2px';

        setTimeout(() => {
            result.element.style.outline = originalOutline;
            result.element.style.outlineOffset = '';
        }, 3000);
        console.log('🔴 Найденный контейнер подсвечен красным на 3 секунды для визуальной проверки.');
    }
})();
```

---

### 📋 Алгоритм действий для вас (Anna-Ch)

1. Откройте **Microsoft Edge** и перейдите на целевую страницу ОК (например, дискуссия или профиль).
2. Нажмите **F12**, чтобы открыть DevTools.
3. Перейдите на вкладку **Elements** (Элементы).
4. Используйте инструмент выбора (значок стрелки в левом верхнем углу DevTools или `Ctrl+Shift+C`), чтобы **выделить имя автора** комментария, поста или сообщения. Убедитесь, что этот элемент подсвечен в DOM-дереве как `$0`.
5. Перейдите на вкладку **Console** (Консоль).
6. Вставьте предоставленный выше код и нажмите **Enter**.

### 🎯 Что сделает этот код (фиксация фрагмента):
1. **Найдёт** ближайший родительский элемент, соответствующий критериям контейнера события (B5, B9), поднимаясь по DOM-дереву (глубина до 10 уровней).
2. **Сгенерирует** читаемый CSS-селектор для этого контейнера.
3. **Выведет** в консоль строго форматированный блок `[04] EVENT_CONTAINER` с указанием селектора, причины выбора, глубины и превью HTML-кода (первые 300 символов).
4. **Скопирует** этот текстовый блок в ваш буфер обмена (через встроенную функцию `copy()`), чтобы вы могли сразу вставить его в отчётный файл (например, `OK_discussion_01.txt`).
5. **Подсветит** найденный контейнер красной рамкой на 3 секунды, чтобы вы могли визуально подтвердить (PASS/FAIL), что это действительно нужный контейнер события, а не случайный блок.

Если визуальная проверка покажет, что выделен не тот блок (FAIL), просто выберите другой внутренний элемент (например, сам текст комментария, а не имя) и запустите код снова.

