*/

(function() {
    console.log('\n=== СБОР АТОМОВ [05][06] ===\n');

    // Начинаем с выделенного элемента (имя автора или текст)
    const startEl = typeof $0 !== 'undefined' ? $0 : document.querySelector('.discussions_layer_head-title');

    if (!startEl) {
        console.error('❌ Элемент не найден. Выделите имя автора или текст комментария в Elements panel ($0)');
        return;
    }

    // Находим общий контейнер комментария (поднимаемся до уровня элемента, который содержит и имя, и текст, и дату)
    const commentContainer = startEl.closest('.discussions_layer_item') || 
                             startEl.closest('.comments_i') || 
                             startEl.parentElement;

    if (!commentContainer) {
        console.error('❌ Не удалось найти общий контейнер комментария');
