    }
    console.log('');

    // ========== [06] DATE_TIME ==========
    // Ищем элемент с датой/временем. Стратегия: поиск по текстовому паттерну (даты, "сегодня", "вчера") или классам
    let dateEl = null;
    const allElements = commentContainer.querySelectorAll('*');

    for (let el of allElements) {
        const text = el.textContent.trim();
        // Паттерн ищет: 12.05.2023, 12:30, сегодня, вчера, минут назад и т.д.
        // И отсекает слишком длинные тексты (чтобы не захватить сам комментарий)
        if (text.length > 0 && text.length < 60 && 
            (/\d{1,2}[.\-/]\d{1,2}[.\-/]\d{2,4}/.test(text) || 
             /\d{1,2}:\d{2}/.test(text) || 
             /сегодня|вчера|минут|часов|дней|недель/i.test(text))) {

            // Исключаем элементы, которые являются самим текстом комментария
            if (textEl && (el === textEl || textEl.contains(el))) continue;

            dateEl = el;
            break;
        }
