    if (!dateEl) {
        dateEl = commentContainer.querySelector('.discussions_layer_date, .discussion-date, time, .timestamp');
    }

    const dateData = dateEl ? {
        tag: dateEl.tagName.toLowerCase(),
        className: dateEl.className || 'N/A',
        text: dateEl.textContent.trim(),
        selector: getCssSelector(dateEl),
        dataAttributes: getDataAttributes(dateEl)
    } : null;

