    }
    console.log('');

    // ========== ФОРМИРОВАНИЕ ОТЧЕТА ==========
    const report = `
[05] EVENT_TEXT
Tag: ${eventData ? eventData.tag : 'N/A'}
Class: ${eventData ? eventData.className : 'N/A'}
Text Preview: ${eventData ? eventData.text : 'N/A'}
Selector: ${eventData ? eventData.selector : 'N/A'}
Data-attributes: ${eventData ? eventData.dataAttributes : 'N/A'}

[06] DATE_TIME
Tag: ${dateData ? dateData.tag : 'N/A'}
Class: ${dateData ? dateData.className : 'N/A'}
Text: ${dateData ? dateData.text : 'N/A'}
Selector: ${dateData ? dateData.selector : 'N/A'}
Data-attributes: ${dateData ? dateData.dataAttributes : 'N/A'}

---
`;

    console.log('=== ИТОГОВЫЙ ОТЧЕТ ДЛЯ КОПИРОВАНИЯ ===');
    console.log(report);

    try {
        copy(report);
        console.log('✅ Отчет [05][06] скопирован в буфер обмена');
    } catch(e) {
        console.log('⚠️ Скопируйте текст отчета вручную');
    }

    // Подсветка найденных элементов
    if (textEl) highlightElement(textEl, 3000, '#00ff00'); // Зеленый для текста
    if (dateEl) highlightElement(dateEl, 3000, '#0000ff'); // Синий для даты

    // ========== ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ ==========
    function getCssSelector(el) {
        if (!el) return 'N/A';
        if (el.id) return `#${el.id}`;
        let path = [];
        let curr = el;
        while (curr && curr.nodeType === Node.ELEMENT_NODE && path.length < 5) {
            let sel = curr.nodeName.toLowerCase();
            if (curr.className && typeof curr.className === 'string') {
                const classes = curr.className.trim().split(/\s+/).filter(c => c.length > 3).slice(0, 2);
                if (classes.length > 0) sel += '.' + classes.join('.');
            }
            path.unshift(sel);
            curr = curr.parentElement;
        }
        return path.join(' > ');
    }

    function getDataAttributes(el) {
        if (!el) return 'N/A';
        const attrs = [];
        for (let attr of el.attributes) {
            if (attr.name.startsWith('data-')) {
                attrs.push(`${attr.name}="${attr.value.substring(0, 50)}"`);
            }
        }
        return attrs.length > 0 ? attrs.join(', ') : 'N/A';
    }

    function highlightElement(el, duration, color) {
        const originalOutline = el.style.outline;
        el.style.outline = `3px solid ${color}`;
        el.style.outlineOffset = '2px';
        setTimeout(() => {
            el.style.outline = originalOutline;
            el.style.outlineOffset = '';
        }, duration);
    }

    console.log('\n=== КОНЕЦ СБОРА [05][06] ===\n');
})();
