Ниже представлен готовый JavaScript-код, составленный **строго по алгоритмам и принципам** из документов `connecting_a_new_portalinstruction.md` и `INSTRUCTION_OK_ATOMS_A1_A6.md`. 

Этот код предназначен для вставки в **Console** DevTools (F12) браузера Edge на странице ОК. Он находит контейнер события для выбранного элемента и **фиксирует собранный фрагмент** в точном формате 15-секционного отчёта (секция `[04]`), а также копирует его в буфер обмена.

### 🛠️ Код для вставки в Console (F12)

```javascript
(function() {
    // 1. Проверяем, что элемент выбран в панели Elements
    const el = typeof $0 !== 'undefined' ? $0 : null;
    if (!el || el === document.body) {
        console.error('❌ ОШИБКА: Элемент не выбран.\n👉 Пожалуйста, выберите имя автора, текст комментария или поста в панели Elements (F12), затем запустите этот код снова.');
        return;
    }

    console.log(`🔍 Начало анализа выбранного элемента:`, el);

    // 2. Алгоритм поиска EVENT_CONTAINER (строго по принципам connecting_a_new_portalinstruction.md)
    function findEventContainer(element) {
        if (!element) return null;

        // Уровень А: Поиск по явным паттернам классов и ID
        const containers = [
            { test: (e) => e.classList && Array.from(e.classList).some(c => /comment|post|message|entry|item|discuss|thread/i.test(c)), name: 'Matched class pattern (comment/post/message/etc.)' },
            { test: (e) => e.id && /comment|post|message|entry|item/i.test(e.id), name: 'Matched ID pattern' },
            { test: (e) => e.getAttribute('data-test') || e.getAttribute('data-testid'), name: 'Has data-test/data-testid attribute' }
        ];

        let current = element;
        let depth = 0;
        const maxDepth = 10;

        while (current && depth < maxDepth) {
            for (let container of containers) {
                if (container.test(current)) {
                    return {
                        element: current,
                        selector: getCssSelector(current),
                        reason: container.name,
                        depth: depth
                    };
                }
            }
            current = current.parentElement;
            depth++;
        }

        // Уровень Б: Эвристический поиск (контейнер с текстом > 50 символов, содержащий автора)
        current = element.parentElement;
        depth = 0;
        while (current && depth < 7) {
            if (current.children && current.children.length > 1) {
                let hasText = false;
                let hasAuthor = false;

                for (let child of current.children) {
                    const text = (child.textContent || '').trim();
                    if (text.length > 50) hasText = true;
                    if (child === element || child.contains(element)) hasAuthor = true;
                }

                if (hasText && hasAuthor) {
                    return {
                        element: current,
                        selector: getCssSelector(current),
                        reason: 'Probable container with text and author (heuristic)',
                        depth: depth
                    };
                }
            }
            current = current.parentElement;
            depth++;
        }

        // Уровень В: Fallback (крайний случай)
        return {
            element: element.closest('body') || element,
            selector: getCssSelector(element.closest('body') || element),
            reason: 'Fallback to body or nearest parent',
            depth: -1
        };
    }

    // Вспомогательная функция для генерации читаемого CSS-селектора
    function getCssSelector(element) {
        if (element.id) return `#${element.id}`;
        if (element === document.body) return 'body';

        let path = [];
        let curr = element;
        while (curr && curr.nodeType === Node.ELEMENT_NODE) {
            let selector = curr.nodeName.toLowerCase();
            if (curr.className && typeof curr.className === 'string') {
                // Берем только первые 1-2 класса, игнорируя короткие или числовые хэши
                const classes = curr.className.trim().split(/\s+/).filter(c => c.length > 3 && !/^\d+$/.test(c)).slice(0, 2);
                if (classes.length > 0) {
                    selector += '.' + classes.join('.');
                }
            }
            path.unshift(selector);
            curr = curr.parentElement;
            if (path.length > 5) break; // Ограничиваем глубину для читаемости отчёта
        }
        return path.join(' > ');
    }

    // 3. Выполняем поиск
