        const candidates = [];

        // Кандидат 1: сам элемент
        candidates.push({
            selector: getCssSelector(el),
            href: el.href || null,
            dataAttrs: getDataAttributes(el),
            parentTag: el.parentElement ? el.parentElement.tagName.toLowerCase() : 'N/A'
        });

        // Кандидат 2: родитель с классом author/username
        let parent = el.parentElement;
        let depth = 0;
        while (parent && depth < 5) {
            if (parent.className && /author|username|user|name/i.test(parent.className)) {
                candidates.push({
                    selector: getCssSelector(parent),
                    href: parent.href || null,
                    dataAttrs: getDataAttributes(parent),
                    parentTag: parent.parentElement ? parent.parentElement.tagName.toLowerCase() : 'N/A'
                });
            }
            parent = parent.parentElement;
            depth++;
        }

        return candidates;
    }

    function highlightElement(el, duration) {
        const originalOutline = el.style.outline;
        const originalBg = el.style.backgroundColor;
        el.style.outline = '3px solid #ff0000';
        el.style.outlineOffset = '2px';
        el.style.backgroundColor = 'rgba(255, 0, 0, 0.2)';

        setTimeout(() => {
            el.style.outline = originalOutline;
            el.style.outlineOffset = '';
            el.style.backgroundColor = originalBg;
        }, duration);
    }

    console.log('\n=== КОНЕЦ СБОРА [01][02][03] ===\n');
})();
