**Цель:** Найти контейнер с текстом комментария и элемент с датой/временем внутри того же блока.

### 💻 КОД:

```javascript
/* 
  СКРИПТ №2 (v1.0)
  Собирает: [05] EVENT_TEXT, [06] DATE_TIME
  Атомы анкеты: A12 (GetEventText), A11 (GetTimestamp)
  Дата: 2026-09-13
  Портал: OK.RU
*/

(function() {
    console.log('\n=== СБОР АТОМОВ [05][06] ===\n');

    // Начинаем с выделенного элемента (имя автора или текст)
    const startEl = typeof $0 !== 'undefined' ? $0 : document.querySelector('.discussions_layer_head-title');

    if (!startEl) {
        console.error('❌ Элемент не найден. Выделите имя автора или текст комментария в Elements panel ($0)');
        return;
    }

    // Находим общий контейнер комментария (поднимаемся до уровня элемента, который содержит и имя, и текст, и дату)
    const commentContainer = startEl.closest('.discussions_layer_item') || 
                             startEl.closest('.comments_i') || 
                             startEl.parentElement;

    if (!commentContainer) {
        console.error('❌ Не удалось найти общий контейнер комментария');
        return;
    }

    console.log('✅ Найден контейнер комментария:', getCssSelector(commentContainer));
    console.log('');

    // ========== [05] EVENT_TEXT ==========
    // Ищем элемент с текстом комментария по известным маркерам
    const textEl = commentContainer.querySelector('[data-tsid="comment-text"], .discussions_layer_text4, .comments_text-inner, .discussion-text');

    const eventData = textEl ? {
        tag: textEl.tagName.toLowerCase(),
        className: textEl.className || 'N/A',
        text: textEl.textContent.trim().substring(0, 150), // Берем первые 150 символов для превью
        selector: getCssSelector(textEl),
        dataAttributes: getDataAttributes(textEl)
    } : null;

    console.log('[05] EVENT_TEXT');
    if (eventData) {
        console.log('Tag:', eventData.tag);
        console.log('Class:', eventData.className);
        console.log('Text Preview:', eventData.text);
        console.log('Selector:', eventData.selector);
        console.log('Data-attributes:', eventData.dataAttributes);
    } else {
        console.log('⚠️ Текст комментария не найден по стандартным селекторам');
    }
    console.log('');

    // ========== [06] DATE_TIME ==========
    // Ищем элемент с датой/временем. Стратегия: поиск по текстовому паттерну (даты, "сегодня", "вчера") или классам
    let dateEl = null;
    const allElements = commentContainer.querySelectorAll('*');

    for (let el of allElements) {
        const text = el.textContent.trim();
        // Паттерн ищет: 12.05.2023, 12:30, сегодня, вчера, минут назад и т.д.
        // И отсекает слишком длинные тексты (чтобы не захватить сам комментарий)
        if (text.length > 0 && text.length < 60 && 
            (/\d{1,2}[.\-/]\d{1,2}[.\-/]\d{2,4}/.test(text) || 
             /\d{1,2}:\d{2}/.test(text) || 
             /сегодня|вчера|минут|часов|дней|недель/i.test(text))) {

            // Исключаем элементы, которые являются самим текстом комментария
            if (textEl && (el === textEl || textEl.contains(el))) continue;

            dateEl = el;
            break;
        }
    }

    // Fallback: если по тексту не нашли, ищем по типичным классам
    if (!dateEl) {
        dateEl = commentContainer.querySelector('.discussions_layer_date, .discussion-date, time, .timestamp');
    }

    const dateData = dateEl ? {
        tag: dateEl.tagName.toLowerCase(),
        className: dateEl.className || 'N/A',
        text: dateEl.textContent.trim(),
        selector: getCssSelector(dateEl),
        dataAttributes: getDataAttributes(dateEl)
    } : null;

    console.log('[06] DATE_TIME');
    if (dateData) {
        console.log('Tag:', dateData.tag);
        console.log('Class:', dateData.className);
        console.log('Text:', dateData.text);
        console.log('Selector:', dateData.selector);
        console.log('Data-attributes:', dateData.dataAttributes);
    } else {
        console.log('⚠️ Дата/время не найдены. Проверьте DOM вручную.');
    }
    console.log('');

    // ========== ФОРМИРОВАНИЕ ОТЧЕТА ==========
    const report = `
[05] EVENT_TEXT
Tag: ${eventData ? eventData.tag : 'N/A'}
Class: ${eventData ? eventData.className : 'N/A'}
Text Preview: ${eventData ? eventData.text : 'N/A'}
Selector: ${eventData ? eventData.selector : 'N/A'}
Data-attributes: ${eventData ? eventData.dataAttributes : 'N/A'}

[06] DATE_TIME
Tag: ${dateData ? dateData.tag : 'N/A'}
Class: ${dateData ? dateData.className : 'N/A'}
Text: ${dateData ? dateData.text : 'N/A'}
Selector: ${dateData ? dateData.selector : 'N/A'}
Data-attributes: ${dateData ? dateData.dataAttributes : 'N/A'}

---
`;

    console.log('=== ИТОГОВЫЙ ОТЧЕТ ДЛЯ КОПИРОВАНИЯ ===');
    console.log(report);

    try {
        copy(report);
        console.log('✅ Отчет [05][06] скопирован в буфер обмена');
    } catch(e) {
        console.log('⚠️ Скопируйте текст отчета вручную');
    }

    // Подсветка найденных элементов
    if (textEl) highlightElement(textEl, 3000, '#00ff00'); // Зеленый для текста
    if (dateEl) highlightElement(dateEl, 3000, '#0000ff'); // Синий для даты

    // ========== ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ ==========
    function getCssSelector(el) {
        if (!el) return 'N/A';
        if (el.id) return `#${el.id}`;
        let path = [];
        let curr = el;
        while (curr && curr.nodeType === Node.ELEMENT_NODE && path.length < 5) {
            let sel = curr.nodeName.toLowerCase();
            if (curr.className && typeof curr.className === 'string') {
                const classes = curr.className.trim().split(/\s+/).filter(c => c.length > 3).slice(0, 2);
                if (classes.length > 0) sel += '.' + classes.join('.');
            }
            path.unshift(sel);
            curr = curr.parentElement;
        }
        return path.join(' > ');
    }

    function getDataAttributes(el) {
        if (!el) return 'N/A';
        const attrs = [];
        for (let attr of el.attributes) {
            if (attr.name.startsWith('data-')) {
                attrs.push(`${attr.name}="${attr.value.substring(0, 50)}"`);
            }
        }
        return attrs.length > 0 ? attrs.join(', ') : 'N/A';
    }

    function highlightElement(el, duration, color) {
        const originalOutline = el.style.outline;
        el.style.outline = `3px solid ${color}`;
        el.style.outlineOffset = '2px';
        setTimeout(() => {
            el.style.outline = originalOutline;
            el.style.outlineOffset = '';
        }, duration);
    }

    console.log('\n=== КОНЕЦ СБОРА [05][06] ===\n');
})();
