### 🔧 СКРИПТ №1.4 (ЧИСТЫЙ ДИНАМИЧЕСКИЙ ПОИСК ID)
**Задача:** Найти реальный числовой ID в атрибутах выделенного элемента или его родителей без каких-либо догадок.

### 💻 КОД:

```javascript
/* 
  СКРИПТ №1.4 (ЧИСТЫЙ ПОИСК)
  Задача: Динамический поиск User ID в DOM без галлюцинаций.
  Атом: A4 (GetUserAlias)
*/
(function() {
    const el = typeof $0 !== 'undefined' ? $0 : null;

    if (!el) {
        console.error('❌ ОШИБКА: Элемент не выбран.\n👉 Выделите имя автора (например, "Вера Селиверстова") в панели Elements (F12) и запустите скрипт снова.');
        return;
    }

    console.log('\n=== ДИНАМИЧЕСКИЙ ПОИСК ID (БЕЗ ЗАШИТЫХ ЗНАЧЕНИЙ) ===');
    console.log('Текст выделенного элемента:', `"${el.textContent.trim()}"`);
    console.log('Тег:', el.tagName.toLowerCase());
    console.log('Классы:', el.className);
    console.log('=======================================================\n');

    let current = el;
    let depth = 0;
    let foundId = null;

    // Поднимаемся по дереву до 10 уровней, ищем атрибуты
    while (current && depth < 10) {
        console.log(`[Уровень ${depth}] <${current.tagName.toLowerCase()}>`);

        let hasRelevantAttrs = false;

        for (let attr of current.attributes) {
            // Выводим ключевые атрибуты для анализа
            if (attr.name.match(/^(data-|href|onclick|role|aria-)/i)) {
                console.log(`  ├── ${attr.name} = "${attr.value}"`);
                hasRelevantAttrs = true;
            }

            // Эвристика 1: Ищем атрибуты с именем, содержащим id/mid/uid, и значением из 8-15 цифр
            if (attr.name.match(/mid|uid|user_id|author_id/i) && attr.value.match(/^\d{8,15}$/)) {
                console.log(`  ✅ ПОТЕНЦИАЛЬНЫЙ ID НАЙДЕН: ${attr.value} (в атрибуте ${attr.name})`);
                foundId = { id: attr.value, attr: attr.name, element: current };
            }

            // Эвристика 2: Ищем href с профилем
            if (attr.name === 'href' && attr.value.includes('/profile/')) {
                const match = attr.value.match(/\/profile\/(\d+)/);
                if (match) {
                    console.log(`  ✅ ID ИЗ HREF: ${match[1]}`);
                    foundId = { id: match[1], attr: 'href', element: current };
                }
            }

            // Эвристика 3: Ищем onclick или data-nav с ID
            if ((attr.name === 'onclick' || attr.name === 'data-nav') && attr.value.match(/st\.mid=(\d+)/)) {
                const match = attr.value.match(/st\.mid=(\d+)/);
                console.log(`  ✅ ID ИЗ ${attr.name}: ${match[1]}`);
                foundId = { id: match[1], attr: attr.name, element: current };
            }
        }

        if (!hasRelevantAttrs) {
            console.log('  └── (нет data-*, href, onclick или aria- атрибутов)');
        }

        if (foundId) break; // Останавливаем поиск, если ID найден

        current = current.parentElement;
        depth++;
    }

    console.log('\n=======================================================');
    console.log('=== ИТОГОВЫЙ ВЕРДИКТ ===');

    if (foundId) {
        console.log(`✅ User ID найден: ${foundId.id}`);
        console.log(`✅ URL профиля: https://ok.ru/profile/${foundId.id}`);
        console.log(`✅ Источник: атрибут "${foundId.attr}" на уровне ${depth}`);

        const report = `
[03] ENTITY_CANDIDATES (PROFILE)
User ID: ${foundId.id}
href: https://ok.ru/profile/${foundId.id}
Found via: Dynamic DOM scan (attribute: ${foundId.attr})
Element selector: ${getCssSelector(foundId.element)}
---
`;
        console.log('\n📋 ОТЧЕТ ДЛЯ КОПИРОВАНИЯ:');
        console.log(report);
        try { copy(report); console.log('✅ Скопировано в буфер'); } catch(e) {}
    } else {
        console.log('❌ Числовой User ID НЕ НАЙДЕН в пределах 10 уровней вложенности.');
        console.log('💡 Возможные причины:');
        console.log('   1. ID хранится в зашифрованном виде (не только цифры).');
        console.log('   2. Переход на профиль осуществляется через JS-событие без явного ID в атрибутах.');
        console.log('   3. Это тестовый режим ОК, где ID заменены на заглушки (как "ava-picture-test-id").');
        console.log('👉 ДЕЙСТВИЕ: Пришлите полный вывод консоли выше, я проанализирую атрибуты вручную.');
    }
    console.log('=======================================================\n');

    function getCssSelector(element) {
        if (!element) return 'N/A';
        if (element.id) return `#${element.id}`;
        let path = [];
        let curr = element;
        while (curr && curr.nodeType === Node.ELEMENT_NODE && path.length < 5) {
            let sel = curr.nodeName.toLowerCase();
            if (curr.className && typeof curr.className === 'string') {
                const classes = curr.className.trim().split(/\s+/).filter(c => c.length > 3).slice(0, 2);
                if (classes.length > 0) sel += '.' + classes.join('.');
            }
            path.unshift(sel);
            curr = curr.parentElement;
        }
        return path.join(' > ');
    }
})();
